// dsh-rule-manager client bundle: registers a "规则管理" settings section
// with three tabs — "全局规则" (edit ~/.dsh/AGENTS.md), "项目规则" (read/write
// workspace AGENTS.md) and "自动拆分" (paste rules, LLM splits them into
// layered AGENTS.md files). Host routes stay identical to the merged plugins:
// /global-rules, /rule-splitter/workspaces, /rule-splitter/models,
// /rule-splitter/rules, /rule-splitter/rule-files, /rule-splitter/split,
// /rule-splitter/apply.
// Hand-written __ModuleLoader__ factory (no build step). The only external
// require is react, which the loader module table provides.
window.__ModuleLoader__.load({ id: "dsh-rule-manager", factory: (require) => {

	var module = { exports: {} };
	var exports = module.exports;
	Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });
	let react = require("react");
	const h = react.createElement;
	const { useState, useEffect, useCallback } = react;

	const name = "rule-manager";
	const inject = ["slots"];

	const TEXTAREA_STYLE = {
		width: "100%",
		minHeight: "300px",
		boxSizing: "border-box",
		fontFamily: "ui-monospace, 'Cascadia Mono', Consolas, monospace",
		fontSize: "13px",
		lineHeight: 1.5,
		padding: "10px",
		background: "transparent",
		color: "inherit",
		border: "1px solid rgba(128, 128, 128, 0.35)",
		borderRadius: "6px",
		resize: "vertical",
	};

	const ROW_STYLE = {
		display: "flex",
		alignItems: "center",
		gap: "10px",
		marginTop: "10px",
		flexWrap: "wrap",
	};

	const SELECT_STYLE = {
		padding: "6px 10px",
		borderRadius: "6px",
		border: "1px solid rgba(128, 128, 128, 0.35)",
		background: "transparent",
		color: "inherit",
		fontSize: "13px",
		maxWidth: "420px",
		width: "100%",
		boxSizing: "border-box",
	};

	const BUTTON_STYLE = {
		padding: "6px 16px",
		borderRadius: "6px",
		border: "none",
		cursor: "pointer",
		fontSize: "13px",
	};

	const TAB_BAR_STYLE = {
		display: "flex",
		gap: "6px",
		marginBottom: "14px",
		borderBottom: "1px solid rgba(128, 128, 128, 0.25)",
		paddingBottom: "8px",
	};

	const TAB_STYLE = {
		padding: "6px 16px",
		borderRadius: "6px",
		border: "1px solid transparent",
		cursor: "pointer",
		fontSize: "13px",
		background: "transparent",
		color: "inherit",
		opacity: 0.65,
	};

	const TAB_ACTIVE_STYLE = Object.assign({}, TAB_STYLE, {
		opacity: 1,
		border: "1px solid rgba(128, 128, 128, 0.35)",
		background: "rgba(128, 128, 128, 0.12)",
	});

	const RESULT_BOX_STYLE = {
		marginTop: "12px",
		padding: "10px 12px",
		borderRadius: "6px",
		border: "1px solid rgba(128, 128, 128, 0.25)",
		fontSize: "13px",
		lineHeight: 1.6,
		maxHeight: "300px",
		overflowY: "auto",
	};

	function WorkspaceSelect({ workspaces, selectedId, onChange, disabled }) {
		return h("select", {
			style: SELECT_STYLE,
			value: selectedId,
			onChange: (event) => onChange(event.target.value),
			disabled: disabled || workspaces.length === 0,
		},
			workspaces.length === 0
				? h("option", { value: "" }, "暂无可用的工作区")
				: workspaces.map((ws) => h("option", { key: ws.id, value: ws.id },
					ws.title + "  (" + ws.path + ")")),
		);
	}

	// ── Tab 1: 全局规则（原 dsh-global-rules）───────────────────────────────
	function GlobalRulesTab() {
		const [content, setContent] = useState("");
		const [loaded, setLoaded] = useState(false);
		const [exists, setExists] = useState(true);
		const [saving, setSaving] = useState(false);
		const [notice, setNotice] = useState({ kind: "idle", text: "" });
		const [home, setHome] = useState("");

		useEffect(() => {
			let cancelled = false;
			fetch("/global-rules", { cache: "no-store" })
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (cancelled) return;
					setContent(String(data.content || ""));
					setExists(Boolean(data.exists));
					setHome(String(data.home || ""));
					setLoaded(true);
				})
				.catch((error) => {
					if (cancelled) return;
					setNotice({ kind: "error", text: "读取失败: " + error.message });
					setLoaded(true);
				});
			return () => { cancelled = true; };
		}, []);

		const save = useCallback(() => {
			setSaving(true);
			setNotice({ kind: "idle", text: "" });
			fetch("/global-rules", {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ content }),
			})
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (data.ok) {
						setExists(true);
						setNotice({
							kind: "ok",
							text: "已保存。新会话立即生效；当前会话将在下一次文件操作后感知新规则。",
						});
					} else {
						setNotice({ kind: "error", text: "保存失败: " + (data.error || "未知错误") });
					}
				})
				.catch((error) => {
					setNotice({ kind: "error", text: "保存失败: " + error.message });
				})
				.finally(() => setSaving(false));
		}, [content]);

		return h("div", { style: { maxWidth: "720px" } },
			h("p", { style: { marginTop: 0, opacity: 0.75, fontSize: "13px" } },
				"编辑 " + (home || "~/.dsh") + "/AGENTS.md 全局规则，保存后实时生效。"),
			exists ? null : h("p", { style: { color: "inherit", opacity: 0.75, fontSize: "13px" } },
				"文件尚不存在，保存将创建它。"),
			!loaded ? h("p", { style: { opacity: 0.6 } }, "加载中…") : h("textarea", {
				style: TEXTAREA_STYLE,
				value: content,
				onChange: (event) => setContent(event.target.value),
				spellCheck: false,
				placeholder: "# 全局规则\n\n在这里编写对每个会话生效的指令…",
			}),
			h("div", { style: ROW_STYLE },
				h("button", {
					style: Object.assign({}, BUTTON_STYLE, {
						background: "var(--accent, #2f81f7)",
						color: "#fff",
						opacity: saving ? 0.6 : 1,
					}),
					disabled: saving,
					onClick: save,
				}, saving ? "保存中…" : "保存"),
				notice.kind === "ok" ? h("span", { style: { fontSize: "13px", color: "inherit", opacity: 0.85 } }, notice.text)
					: notice.kind === "error" ? h("span", { style: { fontSize: "13px", color: "#e5484d" } }, notice.text)
					: null,
			),
		);
	}

	// ── Tab 2: 项目规则编辑（原 dsh-rule-splitter 编辑 tab）─────────────────
	function EditTab({ workspaces }) {
		const [selectedId, setSelectedId] = useState("");
		const [ruleFiles, setRuleFiles] = useState([]);
		const [selectedFile, setSelectedFile] = useState("");
		const [content, setContent] = useState("");
		const [loaded, setLoaded] = useState(false);
		const [exists, setExists] = useState(true);
		const [saving, setSaving] = useState(false);
		const [notice, setNotice] = useState({ kind: "idle", text: "" });
		const [workspacePath, setWorkspacePath] = useState("");

		useEffect(() => {
			if (workspaces.length > 0 && selectedId === "") setSelectedId(workspaces[0].id);
		}, [workspaces, selectedId]);

		// Load every AGENTS.md (root + subdirs) under the selected workspace.
		useEffect(() => {
			if (selectedId === "") return;
			let cancelled = false;
			setRuleFiles([]);
			setSelectedFile("");
			setLoaded(false);
			fetch("/rule-splitter/rule-files?workspace=" + encodeURIComponent(selectedId), { cache: "no-store" })
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (cancelled) return;
					const list = Array.isArray(data.files) ? data.files : [];
					setRuleFiles(list);
					if (list.length > 0) setSelectedFile(list[0].relPath);
					else setLoaded(true);
				})
				.catch((error) => {
					if (cancelled) return;
					setNotice({ kind: "error", text: "规则文件列表加载失败: " + error.message });
					setLoaded(true);
				});
			return () => { cancelled = true; };
		}, [selectedId]);

		// Load the selected rule file's content.
		useEffect(() => {
			if (selectedId === "" || selectedFile === undefined) return;
			let cancelled = false;
			setLoaded(false);
			setNotice({ kind: "idle", text: "" });
			fetch("/rule-splitter/rules?workspace=" + encodeURIComponent(selectedId) + "&file=" + encodeURIComponent(selectedFile), { cache: "no-store" })
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (cancelled) return;
					setContent(String(data.content || ""));
					setExists(Boolean(data.exists));
					setWorkspacePath(String(data.path || ""));
					setLoaded(true);
				})
				.catch((error) => {
					if (cancelled) return;
					setNotice({ kind: "error", text: "读取失败: " + error.message });
					setLoaded(true);
				});
			return () => { cancelled = true; };
		}, [selectedId, selectedFile]);

		const save = useCallback(() => {
			if (selectedId === "") {
				setNotice({ kind: "error", text: "请先选择一个工作区" });
				return;
			}
			setSaving(true);
			setNotice({ kind: "idle", text: "" });
			fetch("/rule-splitter/rules?workspace=" + encodeURIComponent(selectedId) + "&file=" + encodeURIComponent(selectedFile), {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ content }),
			})
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (data.ok) {
						setExists(true);
						setNotice({ kind: "ok", text: "已保存。新会话立即生效；当前会话将在下一次文件操作后感知新规则。" });
					} else {
						setNotice({ kind: "error", text: "保存失败: " + (data.error || "未知错误") });
					}
				})
				.catch((error) => {
					setNotice({ kind: "error", text: "保存失败: " + error.message });
				})
				.finally(() => setSaving(false));
		}, [content, selectedId, selectedFile]);

		return h("div", null,
			h("div", { style: ROW_STYLE },
				h(WorkspaceSelect, { workspaces, selectedId, onChange: setSelectedId }),
			),
			h("div", { style: Object.assign({}, ROW_STYLE, { marginTop: "10px" }) },
				h("label", { style: { fontSize: "13px", opacity: 0.85 } }, "规则文件："),
				h("select", {
					style: SELECT_STYLE,
					value: selectedFile,
					onChange: (event) => setSelectedFile(event.target.value),
					disabled: ruleFiles.length === 0,
				},
					ruleFiles.length === 0
						? h("option", { value: "" }, "暂无规则文件")
						: ruleFiles.map((f) => h("option", { key: f.relPath, value: f.relPath },
							f.displayPath + (f.exists ? "" : "（未创建）"))),
				),
			),
			workspacePath !== "" && selectedFile !== "" ? h("p", { style: { opacity: 0.6, fontSize: "12px", marginTop: "4px" } },
				"规则文件: " + workspacePath + "\\" + selectedFile.split("/").join("\\")) : null,
			exists ? null : h("p", { style: { opacity: 0.75, fontSize: "13px" } },
				"该文件尚不存在，保存将创建它。"),
			!loaded ? h("p", { style: { opacity: 0.6 } }, "加载中…") : h("textarea", {
				style: TEXTAREA_STYLE,
				value: content,
				onChange: (event) => setContent(event.target.value),
				spellCheck: false,
				placeholder: "# 项目规则\n\n在这里编写对该目录及其子目录生效的指令…",
			}),
			h("div", { style: ROW_STYLE },
				h("button", {
					style: Object.assign({}, BUTTON_STYLE, {
						background: "var(--accent, #2f81f7)",
						color: "#fff",
						opacity: saving ? 0.6 : 1,
					}),
					disabled: saving || selectedId === "" || selectedFile === undefined,
					onClick: save,
				}, saving ? "保存中…" : "保存"),
				notice.kind === "ok" ? h("span", { style: { fontSize: "13px", opacity: 0.85 } }, notice.text)
					: notice.kind === "error" ? h("span", { style: { fontSize: "13px", color: "#e5484d" } }, notice.text)
					: null,
			),
		);
	}

	// ── Tab 3: 自动拆分（原 dsh-rule-splitter 拆分 tab）─────────────────────
	function SplitTab({ workspaces }) {
		const [selectedId, setSelectedId] = useState("");
		const [rules, setRules] = useState("");
		const [splitting, setSplitting] = useState(false);
		const [notice, setNotice] = useState({ kind: "idle", text: "" });
		const [results, setResults] = useState(null);
		const [catalog, setCatalog] = useState([]);
		const [selectedProvider, setSelectedProvider] = useState("");
		const [selectedModel, setSelectedModel] = useState("");
		const [expanded, setExpanded] = useState({});
		const [applying, setApplying] = useState(false);
		const [applied, setApplied] = useState(false);
		const [mode, setMode] = useState("overwrite");

		// Load workspace default selection + model catalog once on mount.
		useEffect(() => {
			let cancelled = false;
			fetch("/rule-splitter/models", { cache: "no-store" })
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (cancelled) return;
					const providers = Array.isArray(data.providers) ? data.providers : [];
					setCatalog(providers);
					const defProvider = data.default?.provider || "";
					const defModel = data.default?.model || "";
					setSelectedProvider(defProvider);
					setSelectedModel(defModel);
				})
				.catch(() => {});
			return () => { cancelled = true; };
		}, []);

		useEffect(() => {
			if (workspaces.length > 0 && selectedId === "") setSelectedId(workspaces[0].id);
		}, [workspaces, selectedId]);

		// When the provider changes, switch model to that provider's first model.
		const providerModels = catalog.find((p) => p.id === selectedProvider)?.models || [];
		const changeProvider = useCallback((providerId) => {
			setSelectedProvider(providerId);
			const models = catalog.find((p) => p.id === providerId)?.models || [];
			if (models.length > 0) setSelectedModel(models[0].id);
			else setSelectedModel("");
		}, [catalog]);

		const split = useCallback(() => {
			if (selectedId === "") {
				setNotice({ kind: "error", text: "请先选择一个工作区" });
				return;
			}
			if (rules.trim() === "") {
				setNotice({ kind: "error", text: "请先粘贴规则内容" });
				return;
			}
			setSplitting(true);
			setNotice({ kind: "idle", text: mode === "merge" ? "正在调用模型拆分并融合原规则，请稍候（最多 3 分钟）…" : "正在调用模型拆分规则，请稍候（最多 3 分钟）…" });
			setResults(null);
			setExpanded({});
			setApplied(false);
			fetch("/rule-splitter/split", {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ workspaceId: selectedId, rules, mode, provider: selectedProvider, model: selectedModel }),
			})
				.then((res) => res.json())
				.then((data) => {
					if (data.ok) {
						setResults(data.files || []);
						const modelLabel = (data.model ? (data.model.provider + "/" + data.model.model) : "默认模型");
						const modeLabel = data.mode === "merge" ? "（合并模式：已融合原规则）" : "（直接覆盖模式）";
						setNotice({
							kind: "ok",
							text: "拆分完成（" + modelLabel + "）" + modeLabel + "，共 " + (data.files ? data.files.length : 0) + " 个文件。请先预览确认，再点击「确认生成」写入工作区。",
						});
					} else {
						setNotice({ kind: "error", text: "拆分失败: " + (data.error || "未知错误") });
					}
				})
				.catch((error) => {
					setNotice({ kind: "error", text: "拆分失败: " + error.message });
				})
				.finally(() => setSplitting(false));
		}, [selectedId, rules, selectedProvider, selectedModel, mode]);

		// Confirm: actually write the previewed files into the workspace.
		const apply = useCallback(() => {
			if (results === null || results.length === 0 || applied) return;
			setApplying(true);
			setNotice({ kind: "idle", text: "正在写入文件…" });
			fetch("/rule-splitter/apply", {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ workspaceId: selectedId, files: results, mode, provider: selectedProvider, model: selectedModel }),
			})
				.then((res) => res.json())
				.then((data) => {
					if (data.ok) {
						setApplied(true);
						const written = data.files || [];
						const overwritten = written.filter((f) => f.backupPath).length;
						if (mode === "merge") {
							setNotice({
								kind: "ok",
								text: "已生成 " + written.length + " 个文件（合并模式，已融合原规则）" + (overwritten > 0 ? "，原文件已备份" : "") + "。新会话立即生效。",
							});
						} else {
							setNotice({
								kind: "ok",
								text: "已生成 " + written.length + " 个文件" + (overwritten > 0 ? "，其中 " + overwritten + " 个覆盖了原文件（已备份）" : "") + "。新会话立即生效；当前会话将在下一次文件操作后感知新规则。",
							});
						}
					} else {
						setNotice({ kind: "error", text: "写入失败: " + (data.error || "未知错误") });
					}
				})
				.catch((error) => {
					setNotice({ kind: "error", text: "写入失败: " + error.message });
				})
				.finally(() => setApplying(false));
		}, [results, selectedId, applied, mode, selectedProvider, selectedModel]);

		return h("div", null,
			h("p", { style: { marginTop: 0, opacity: 0.75, fontSize: "13px" } },
				"粘贴你的项目规则，先选择生成方式再开始拆分。规则多时 AI 会把根 AGENTS.md 拆成精简索引 + 按主题的 .dsh/skills/<主题>/SKILL.md 技能文件，模型平时只看摘要、任务匹配时才加载全文（按需读取）。「直接覆盖」替换原文件（自动备份）；「合并」融合工作区原有规则。拆分后先预览，确认后再写入。"),
			h("div", { style: ROW_STYLE },
				h(WorkspaceSelect, { workspaces, selectedId, onChange: setSelectedId }),
			),
			h("div", { style: Object.assign({}, ROW_STYLE, { marginTop: "10px" }) },
				h("label", { style: { fontSize: "13px", opacity: 0.85 } }, "拆分模型："),
				h("select", {
					style: SELECT_STYLE,
					value: selectedProvider,
					onChange: (event) => changeProvider(event.target.value),
					disabled: catalog.length === 0,
				},
					catalog.length === 0
						? h("option", { value: "" }, "加载模型中…")
						: catalog.map((p) => h("option", { key: p.id, value: p.id }, p.name))),
				providerModels.length > 0 ? h("select", {
					style: Object.assign({}, SELECT_STYLE, { maxWidth: "260px" }),
					value: selectedModel,
					onChange: (event) => setSelectedModel(event.target.value),
				},
					providerModels.map((m) => h("option", { key: m.id, value: m.id }, m.name)),
				) : null,
			),
			h("div", { style: Object.assign({}, ROW_STYLE, { marginTop: "10px" }) },
				h("label", { style: { fontSize: "13px", opacity: 0.85 } }, "生成方式："),
				h("button", {
					style: Object.assign({}, BUTTON_STYLE, {
						background: "transparent",
						color: "inherit",
						border: mode === "overwrite" ? "1px solid var(--accent, #2f81f7)" : "1px solid rgba(128,128,128,0.35)",
						opacity: mode === "overwrite" ? 1 : 0.65,
					}),
					onClick: () => setMode("overwrite"),
				}, "直接覆盖"),
				h("button", {
					style: Object.assign({}, BUTTON_STYLE, {
						background: "transparent",
						color: "inherit",
						border: mode === "merge" ? "1px solid var(--accent, #2f81f7)" : "1px solid rgba(128,128,128,0.35)",
						opacity: mode === "merge" ? 1 : 0.65,
					}),
					onClick: () => setMode("merge"),
				}, "合并（保留原规则）"),
			),
			h("div", { style: Object.assign({}, ROW_STYLE, { marginTop: "12px" }) },
				h("label", { style: { fontSize: "13px", opacity: 0.85 } }, "项目规则原文："),
			),
			h("textarea", {
				style: TEXTAREA_STYLE,
				value: rules,
				onChange: (event) => setRules(event.target.value),
				spellCheck: false,
				placeholder: "# 项目规则\n\n在这里粘贴你的全部规则，例如：\n- 前端组件规范…\n- 后端 API 规范…\n- 数据库约定…\n- 文档规范…",
			}),
			h("div", { style: ROW_STYLE },
				h("button", {
					style: Object.assign({}, BUTTON_STYLE, {
						background: "var(--accent, #2f81f7)",
						color: "#fff",
						opacity: splitting ? 0.6 : 1,
					}),
					disabled: splitting || selectedId === "",
					onClick: split,
				}, splitting ? "拆分中…" : "开始拆分"),
				notice.kind === "ok" ? h("span", { style: { fontSize: "13px", opacity: 0.85 } }, notice.text)
					: notice.kind === "error" ? h("span", { style: { fontSize: "13px", color: "#e5484d" } }, notice.text)
					: h("span", { style: { fontSize: "13px", opacity: 0.6 } }, notice.text),
			),
			results !== null ? h("div", { style: RESULT_BOX_STYLE },
				h("div", { style: { fontWeight: 600, marginBottom: "8px" } },
					applied ? "已生成的文件（点击文件名查看内容）：" : "预览（点击文件名查看内容，确认后才会写入）："),
				results.map((file, index) => {
					const isOpen = Boolean(expanded[index]);
					const label = file.path || (file.dir === "." || file.dir === "" ? "AGENTS.md" : file.dir + "/AGENTS.md");
					return h("div", { key: index, style: { marginBottom: "6px" } },
						h("div", { style: { display: "flex", alignItems: "center", gap: "8px" } },
							h("button", {
								style: {
									background: "transparent",
									border: "none",
									cursor: "pointer",
									color: "var(--accent, #2f81f7)",
									fontSize: "13px",
									fontFamily: "ui-monospace, 'Cascadia Mono', Consolas, monospace",
									padding: "4px 0",
									textAlign: "left",
								},
								onClick: () => setExpanded((prev) => ({ ...prev, [index]: !prev[index] })),
							}, (isOpen ? "▾ " : "▸ ") + label),
							file.backupPath ? h("span", { style: { opacity: 0.55, fontSize: "12px" } }, "（已备份原文件）")
								: file.overwrites ? h("span", { style: { opacity: 0.6, fontSize: "12px", color: "#d29922" } }, "（将覆盖原文件）")
								: null,
						),
						isOpen ? h("pre", { style: { fontSize: "12px", lineHeight: 1.5, margin: "4px 0 8px 18px", padding: "8px 10px", whiteSpace: "pre-wrap", wordBreak: "break-word", opacity: 0.88, background: "rgba(128,128,128,0.08)", borderRadius: "6px" } },
							file.content || "") : null,
					);
				}),
				!applied ? h("div", { style: Object.assign({}, ROW_STYLE, { marginTop: "12px" }) },
					h("span", { style: { fontSize: "13px", opacity: 0.7 } }, "生成方式：" + (mode === "merge" ? "合并（保留原规则）" : "直接覆盖") + "　"),
					h("button", {
						style: Object.assign({}, BUTTON_STYLE, {
							background: "var(--accent, #2f81f7)",
							color: "#fff",
							opacity: applying ? 0.6 : 1,
						}),
						disabled: applying,
						onClick: apply,
					}, applying ? "写入中…" : "确认生成"),
				) : null,
			) : null,
		);
	}

	// ── Section shell: tab bar + 全局规则 / 项目规则 / 自动拆分 ─────────────
	function RulesSection() {
		const [workspaces, setWorkspaces] = useState([]);
		const [tab, setTab] = useState("global");
		const [notice, setNotice] = useState({ kind: "idle", text: "" });

		// 项目规则与自动拆分两个 tab 需要工作区列表，挂载时统一加载。
		useEffect(() => {
			let cancelled = false;
			fetch("/rule-splitter/workspaces", { cache: "no-store" })
				.then((res) => {
					if (!res.ok) throw new Error("HTTP " + res.status);
					return res.json();
				})
				.then((data) => {
					if (cancelled) return;
					const list = Array.isArray(data.workspaces) ? data.workspaces : [];
					setWorkspaces(list);
				})
				.catch((error) => {
					if (cancelled) return;
					setNotice({ kind: "error", text: "工作区列表加载失败: " + error.message });
				});
			return () => { cancelled = true; };
		}, []);

		return h("div", { style: { maxWidth: "760px" } },
			h("div", { style: TAB_BAR_STYLE },
				h("button", { style: tab === "global" ? TAB_ACTIVE_STYLE : TAB_STYLE, onClick: () => setTab("global") }, "全局规则"),
				h("button", { style: tab === "edit" ? TAB_ACTIVE_STYLE : TAB_STYLE, onClick: () => setTab("edit") }, "项目规则"),
				h("button", { style: tab === "split" ? TAB_ACTIVE_STYLE : TAB_STYLE, onClick: () => setTab("split") }, "自动拆分"),
			),
			notice.kind === "error" ? h("p", { style: { fontSize: "13px", color: "#e5484d", marginTop: 0 } }, notice.text) : null,
			tab === "global"
				? h(GlobalRulesTab, null)
				: tab === "edit"
					? h(EditTab, { workspaces })
					: h(SplitTab, { workspaces }),
		);
	}

	function apply(ctx) {
		ctx.slots.inject("settings.section", () => ctx.slots.register({
			name: "settings.section",
			id: "rule-manager",
			order: 30,
			label: () => "规则管理",
		}, () => h(RulesSection, null)));
	}

	exports.name = name;
	exports.inject = inject;
	exports.apply = apply;
	return module.exports;
}
});
